import urllib.request
import re

url = "https://github.com/divakarpandey07/AI-Palmistry-pro/actions/runs/30088156247"
req = urllib.request.Request(url, headers={
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"
})

try:
    with urllib.request.urlopen(req) as resp:
        html = resp.read().decode("utf-8", errors="ignore")
        job_urls = re.findall(r'/divakarpandey07/AI-Palmistry-pro/actions/runs/30088156247/job/\d+', html)
        job_urls = list(dict.fromkeys(job_urls))
        print("Job URLs for 30088156247:", job_urls)
        if job_urls:
            jurl = "https://github.com" + job_urls[0]
            print(f"Fetching job: {jurl}")
            req_j = urllib.request.Request(jurl, headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"
            })
            with urllib.request.urlopen(req_j) as resp_j:
                jhtml = resp_j.read().decode("utf-8", errors="ignore")
                clean_text = re.sub(r'<[^>]+>', '\n', jhtml)
                lines = [l.strip() for l in clean_text.splitlines() if l.strip()]
                for l in lines:
                    if any(k in l.lower() for k in ["error", "fail", "exit code", "chmod", "gradle"]):
                        print("  ", l[:120])
except Exception as e:
    print(f"Error: {e}")

import urllib.request
import json
import time
import subprocess
import os

def log(msg):
    print(f"[{time.strftime('%H:%M:%S')}] {msg}", flush=True)

def get_latest_run():
    url = "https://api.github.com/repos/divakarpandey07/AI-Palmistry-pro/actions/runs?per_page=1"
    req = urllib.request.Request(url, headers={
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
        "Accept": "application/vnd.github.v3+json"
    })
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            runs = data.get("workflow_runs", [])
            if runs:
                return runs[0]
    except Exception as e:
        log(f"API Error: {e}")
    return None

def get_job_failure_details(jobs_url):
    req = urllib.request.Request(jobs_url, headers={
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)",
        "Accept": "application/vnd.github.v3+json"
    })
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            for j in data.get("jobs", []):
                for step in j.get("steps", []):
                    if step.get("conclusion") == "failure":
                        return j["name"], step["name"]
    except Exception as e:
        log(f"Jobs API Error: {e}")
    return "build", "unknown step"

log("Starting Automated Build Monitor...")
latest_run = get_latest_run()
if latest_run:
    run_id = latest_run['id']
    status = latest_run['status']
    conclusion = latest_run['conclusion']
    sha = latest_run['head_sha'][:7]
    log(f"Latest Run ID: {run_id} | SHA: {sha} | Status: {status} | Conclusion: {conclusion}")
    if conclusion == "failure":
        job_name, step_name = get_job_failure_details(latest_run['jobs_url'])
        log(f"FAILURE DETECTED in Job '{job_name}', Step '{step_name}'")
    elif conclusion == "success":
        log("SUCCESS! GREEN BUILD ACHIEVED!")
else:
    log("No workflow runs found.")

