/* ==========================================================================
   AI Palmistry Pro - Premium Cosmic Design System & Glassmorphism Stylesheet
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. CSS Reset & Color Tokens
   -------------------------------------------------------------------------- */
:root {
    --bg-dark: #0F0C29;
    --deep-purple: #1A0A2E;
    --card-bg: rgba(45, 27, 105, 0.45);
    --card-border: rgba(124, 58, 237, 0.3);
    --neon-violet: #7C3AED;
    --violet-glow: rgba(124, 58, 237, 0.5);
    --gold-accent: #F59E0B;
    --gold-glow: rgba(245, 158, 11, 0.4);
    --soft-white: #F1F5F9;
    --muted-gray: #94A3B8;
    --error-red: #EF4444;
    --radius-lg: 24px;
    --radius-md: 16px;
    --radius-sm: 10px;
    --font-heading: 'Outfit', 'Cinzel Decorative', sans-serif;
    --font-body: 'Noto Serif Devanagari', 'Outfit', sans-serif;
    --transition-fast: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: var(--font-body);
}

body {
    background-color: var(--bg-dark);
    color: var(--soft-white);
    min-height: 100vh;
    overflow-x: hidden;
    position: relative;
}

/* Starfield Background Canvas */
#starsCanvas {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 0;
    pointer-events: none;
}

/* App Main Container */
#appContainer {
    position: relative;
    z-index: 1;
    max-width: 1320px;
    margin: 0 auto;
    padding: 20px;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

/* --------------------------------------------------------------------------
   2. Header & Glass Navigation
   -------------------------------------------------------------------------- */
.app-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px 30px;
    background: rgba(26, 10, 46, 0.7);
    backdrop-filter: blur(16px);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-lg);
    margin-bottom: 24px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
}

.header-logo {
    display: flex;
    align-items: center;
    gap: 16px;
}

.logo-icon {
    font-size: 2.2rem;
    color: var(--gold-accent);
    filter: drop-shadow(0 0 10px var(--gold-glow));
    animation: floatGlow 3s ease-in-out infinite alternate;
}

@keyframes floatGlow {
    0% { transform: translateY(0); filter: drop-shadow(0 0 10px var(--gold-glow)); }
    100% { transform: translateY(-4px); filter: drop-shadow(0 0 20px var(--gold-accent)); }
}

.logo-text h1 {
    font-family: var(--font-heading);
    font-size: 1.8rem;
    font-weight: 700;
    background: linear-gradient(135deg, #FFF 0%, var(--gold-accent) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.sub-logo {
    font-size: 0.85rem;
    color: var(--muted-gray);
    letter-spacing: 0.5px;
}

.nav-tabs {
    display: flex;
    gap: 10px;
    background: rgba(15, 12, 41, 0.6);
    padding: 6px;
    border-radius: 50px;
    border: 1px solid rgba(255, 255, 255, 0.08);
}

.nav-btn {
    background: transparent;
    border: none;
    color: var(--muted-gray);
    padding: 10px 20px;
    border-radius: 40px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition-fast);
    display: flex;
    align-items: center;
    gap: 8px;
}

.nav-btn:hover {
    color: var(--soft-white);
    background: rgba(124, 58, 237, 0.2);
}

.nav-btn.active {
    background: linear-gradient(135deg, var(--neon-violet), #5B21B6);
    color: var(--soft-white);
    box-shadow: 0 4px 15px var(--violet-glow);
}

/* --------------------------------------------------------------------------
   3. Main Content & Glass Cards
   -------------------------------------------------------------------------- */
.main-content {
    flex: 1;
    display: flex;
    flex-direction: column;
}

.tab-section {
    display: none;
    animation: fadeIn 0.4s ease-out forwards;
}

.tab-section.active {
    display: block;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: translateY(0); }
}

.section-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
}

@media (max-width: 900px) {
    .section-grid { grid-template-columns: 1fr; }
    .app-header { flex-direction: column; gap: 16px; align-items: stretch; text-align: center; }
    .header-logo { justify-content: center; }
    .nav-tabs { overflow-x: auto; justify-content: flex-start; }
}

.glass-card {
    background: var(--card-bg);
    backdrop-filter: blur(20px);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-lg);
    padding: 28px;
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.4);
