    padding: 4px 12px;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
}

/* --------------------------------------------------------------------------
   4. Palm Scanner Viewport & Controls
   -------------------------------------------------------------------------- */
.scanner-viewport {
    position: relative;
    width: 100%;
    height: 380px;
    background: #000;
    border-radius: var(--radius-md);
    border: 2px stroke var(--neon-violet);
    overflow: hidden;
    display: flex;
    justify-content: center;
    align-items: center;
    box-shadow: inset 0 0 20px rgba(0,0,0,0.8);
